/** The `composer` section of `prisma.config.ts` (ADR-0017): statically imports each extension's node-descriptor registry plus the state store; core defines only the types. */
import type * as Layer from 'effect/Layer';
import type { CallerCredentials } from '../caller-credentials.ts';
import type { ContainerDescriptor, ContainerInstance } from '../container.ts';
import type { Graph } from '../graph.ts';
import type { ServiceNode } from '../node.ts';
import type { PreflightFindings, PreflightPayload } from '../preflight.ts';
import type {
  AlchemyStateLayer,
  ApplicationDescriptor,
  AssembleInput,
  Bundle,
  DeployedEntity,
  DevServer,
  Lowering,
  ProvisionerDescriptor,
  ServeInput,
  ServiceLowering,
} from './deploy.ts';

export type { CallerCredentials } from '../caller-credentials.ts';
export type {
  ContainerDescriptor,
  ContainerInstance,
  LocateContainerInput,
} from '../container.ts';
export type {
  PlatformVariableReader,
  PreflightFindings,
  PreflightPayload,
  UnsetPlatformVariable,
} from '../preflight.ts';
export { platformVariableReaderText } from '../preflight.ts';
/** Re-exported because `RunOutcome` hands them to a reporter — reading this surface must not also require the deploy one. */
export type { DeployedEntity } from './deploy.ts';

/**
 * One extension's control-plane registry: everything the deploy pipeline may
 * look up for a node whose `extension` field names this package. `nodes` is
 * keyed by the node's within-extension ID (`node.type` / `build.type`).
 */
export interface ExtensionDescriptor {
  /** The extension's package name, e.g. "@prisma/composer-prisma-cloud" — what a node's `extension` field is matched against. */
  readonly id: string;
  /** ONE registry per extension, keyed by node ID. */
  readonly nodes: Record<string, NodeDescriptor>;
  /** Param provisioners this extension supplies, keyed by need brand (ADR-0031). Core resolves a param's ProvisionNeed against the CONSUMER extension's map. */
  readonly provisions?: ReadonlyMap<symbol, ProvisionerDescriptor>;
  /** Once-per-lowering hook — the application's shared infrastructure (e.g. prisma-cloud's Project). */
  readonly application?: ApplicationDescriptor;
  /**
   * The extension's Alchemy providers — merged across all configured extensions (config order).
   * METHOD SYNTAX REQUIRED, like `preflight`: an extension types `input` against its own client, which assigns here only through method bivariance.
   */
  providers?(input: ProvidersInput): Layer.Layer<never>;
  /** Refuses a loaded graph this extension cannot deploy by throwing `GraphCheckError`. The CLI calls it right after Load in every command that runs Load. Any other throw is a bug. */
  readonly checkGraph?: (graph: Graph) => void;
  /**
   * Deploy-time prerequisite check — the CLI runs it once, after the app's
   * Project/Branch are resolved and BEFORE Alchemy
   * runs. A target uses it to verify platform prerequisites (e.g. that every
   * platform variable a service needs has a value) and throws to abort the
   * deploy. Async: it talks to the platform (ADR-0064).
   *
   * What it returns reaches this same extension's lowering as
   * `LowerContext.preflight`. The payload is the extension's own opaque
   * string; the framework never reads it, and a secret value must never go in
   * it. What it hands `input.report` reaches the deploy report through the
   * framework, not this payload.
   *
   * METHOD SYNTAX REQUIRED, for the same reason ContainerDescriptor's members
   * need it: the framework hands over the erased `PreflightInput<unknown>`,
   * and an extension that types the input against its own client type only
   * assigns here through method bivariance.
   */
  preflight?(input: PreflightInput): Promise<PreflightPayload>;
  /**
   * Destroy-time cleanup — the CLI runs it once, after Alchemy's destroy
   * succeeds and BEFORE the environment's containers are removed. A target uses
   * it to remove infrastructure it owns outside the stack (e.g. the deploy
   * state store, which the destroy above was still reading). Throwing aborts
   * the destroy before the containers go; a target that would rather warn than
   * fail the command handles that itself. Async: it talks to the platform.
   */
  readonly teardown?: (input: TeardownInput) => Promise<void>;
  /**
   * The extension's container lifecycle, when its platform has containers
   * (ADR-0038). The CLI resolves containers after assembly and before
   * Alchemy runs (deploy ensures, destroy locates), and hands each resolved
   * instance to the lowering.
   */
  readonly container?: ContainerDescriptor;
  /**
   * Deploy-run reporting. The CLI begins a session after the graph is loaded
   * and before containers are resolved, and finishes it on every exit path.
   * An extension without one reports nothing, which is the default.
   */
  readonly reporter?: ReporterDescriptor;
  /**
   * The extension's LOCAL TARGET counterpart (ADR-0041; naming, operator
   * 2026-07-23 — "dev" names the user-facing feature only, the seam takes
   * the concept's real noun) — a LAZY reference: an async thunk, never the
   * descriptor object itself. This keeps the production control entry's
   * static import graph free of local-target implementation code (operator
   * directive) — the thunk is one line, dynamically importing the
   * extension's own local-target entry by bare specifier
   * (e.g. `() => import('@prisma/composer-prisma-cloud/local-target').then((m) => m.localTargetDescriptor())`),
   * so nothing local-target-flavored is bundled into, or loaded by, any
   * deploy path.
   */
  readonly localTarget?: () => Promise<LocalTargetDescriptor>;
}

/**
 * The deploy's one state store. It names its owning extension so core knows
 * whose resolved container to pass into `create` (ADR-0038).
 */
export interface StateDescriptor {
  /** The owning extension's id — matched against `ExtensionDescriptor.id`. */
  readonly extension: string;
  /** Build the state layer. `container` is the owning extension's resolved instance; `undefined` when it declared no container descriptor. `credentials` is as `ExtensionDescriptor.providers` receives it. */
  create(
    container: ContainerInstance | undefined,
    credentials?: CallerCredentials,
  ): AlchemyStateLayer;
}

/** What `ExtensionDescriptor.providers` receives. `C` erases to `unknown` at the framework boundary, exactly as on `PreflightInput`. */
export interface ProvidersInput<C = unknown> {
  /** What the caller already authenticated (`LowerOptions.credentials`). Absent means the extension falls back to its own credential protocol. */
  readonly credentials?: CallerCredentials<C> | undefined;
}

/** The resolved deploy context handed to an extension's `preflight` hook. `C` erases to `unknown` at the framework boundary — see CallerCredentials. */
export interface PreflightInput<C = unknown> {
  /** The loaded application graph — the manifest of prerequisites is read from it (`provisionManifest`). */
  readonly graph: Graph;
  /** The calling extension's own resolved container; `undefined` when it declares no container descriptor. Narrow with the extension's guard. */
  readonly container: ContainerInstance | undefined;
  /** The environment name. */
  readonly environment: string;
  /** The app configuration the command read for this environment. */
  readonly configuration: AppConfiguration;
  /** The app secrets the command read for this environment. */
  readonly secrets: AppSecrets;
  /** What the caller has already authenticated, for the platform calls preflight makes. Absent means the extension falls back to its own credential protocol. */
  readonly credentials?: CallerCredentials<C> | undefined;
  /** Hands the deploy how many platform variables the check read and which have no value. */
  readonly report?: ((check: PlatformVariableCheck) => void) | undefined;
  /** Shows the user a warning that does not stop the run. Only `prisma dev` passes it and shows the warnings; deploy passes none. */
  readonly warn?: ((message: string) => void) | undefined;
}

/** What a deploy preflight's check of platform variables found: how many it read, and the ones with no value that nothing requires. */
export interface PlatformVariableCheck extends PreflightFindings {
  readonly checked: number;
}

/** The resolved destroy context handed to an extension's `teardown` hook. */
export interface TeardownInput {
  /** The calling extension's own resolved container; `undefined` when it declares no container descriptor. Narrow with the extension's guard. */
  readonly container: ContainerInstance | undefined;
  /** The environment name. */
  readonly environment: string;
}

/** The deploy context handed to `ReporterDescriptor.begin`. `C` erases to `unknown` at the framework boundary, exactly as on `PreflightInput`. */
export interface ReportBeginInput<C = unknown> {
  /** The resolved application name. */
  readonly appName: string;
  /**
   * The loaded application graph — what this deploy declares. A reporter
   * that records the declared topology reads it here. Reporter
   * implementations only receive this input; a host that CONSTRUCTS it to
   * drive `ReporterDescriptor.begin` itself must now supply the graph it
   * loaded (a breaking addition to this published type).
   */
  readonly graph: Graph;
  /** The environment name. */
  readonly environment: string;
  /** The directory the deploy command was run from — where a reporter reads repository metadata. */
  readonly cwd: string;
  /**
   * An existing report record this deploy is one part of, when whatever
   * invoked Composer created one first — a CI job that opens the record, runs
   * several steps against it, and closes it afterwards. Opaque to core: only
   * the reporter knows what record the id names, and a reporter that receives
   * one joins it instead of creating its own.
   *
   * Takes precedence over any equivalent the reporter reads from the
   * environment, because it was passed deliberately.
   */
  readonly reportId: string | undefined;
  /** What the caller has already authenticated, exactly as `preflight` and the container lifecycle receive it. Present means the reporter must not build a client from the environment. */
  readonly credentials?: CallerCredentials<C> | undefined;
}

/** The deploy context handed to `RunReporter.attach`, once containers exist. */
export interface ReportAttachInput {
  /** The calling extension's own resolved container; `undefined` when it declares no container descriptor. Narrow with the extension's guard. */
  readonly container: ContainerInstance | undefined;
}

/** How a run ended, as a reporter sees it. */
export interface RunOutcome {
  readonly ok: boolean;
  /** The run was interrupted (the engine settled a Ctrl-C or a termination signal) — a kind of not-ok that is not a failure. Only meaningful when `ok` is false. */
  readonly cancelled: boolean;
  /** The failing step's name — the deploy's own error code. `undefined` when the run succeeded. */
  readonly failingStep: string | undefined;
  /** Human-readable detail. `undefined` when the run succeeded. */
  readonly errorMessage: string | undefined;
  /**
   * Everything the run's nodes became on the deployment target, flattened.
   * Core does not interpret a `kind` and neither should the CLI — a reporter
   * reads the kinds its own extension emits and ignores the rest. Empty when
   * the run failed before producing a report.
   */
  readonly entities: readonly DeployedEntity[];
}

/**
 * One run's reporting session. Every method is best-effort by contract:
 * reporting is observability, never a step of the deploy, so an
 * implementation logs its own failures and resolves rather than rejecting.
 * The CLI does not catch, and will not fail a deploy over a report.
 */
export interface RunReporter {
  /**
   * Variables a deploy sets in the process environment while Alchemy plans
   * and applies, so reporting that happens inside the apply can find the run
   * this session belongs to. Read once, after `attach`.
   */
  childEnv(): Readonly<Record<string, string>>;
  /** Called once the extension's own container is resolved, before Alchemy runs — the moment the run's project and branch first exist to be referenced. */
  attach(input: ReportAttachInput): Promise<void>;
  /** Called exactly once, on every exit path including a thrown error. */
  finish(outcome: RunOutcome): Promise<void>;
}

/**
 * Deploy-run reporting — how an extension records that a deploy happened,
 * how far it got, and how it ended. The CLI begins a session after the app's
 * graph is loaded and before its containers are resolved, so a failure while
 * creating them is still reported, and finishes it on every exit path.
 *
 * Deploy only: `destroy` has no reportable shape on the Prisma Cloud side
 * (its build phases name a deploy), so the CLI does not run this hook there.
 */
export interface ReporterDescriptor {
  /**
   * Start a session, or return `undefined` when there is nothing to report
   * against (no credentials, no repository). Never throws. METHOD SYNTAX
   * REQUIRED, like `preflight`: the framework hands over the erased
   * `ReportBeginInput<unknown>`, and a reporter that types the input against
   * its own client type only assigns here through method bivariance.
   */
  begin(input: ReportBeginInput): Promise<RunReporter | undefined>;
}

/** The extension's LOCAL TARGET counterpart (ADR-0041) — the local-target variant OF ExtensionDescriptor, hence the full qualifier. An extension without one is not local-target-capable (cannot back the "dev" feature). */
export interface LocalTargetDescriptor {
  /** Local providers for the SAME resource types this extension's lowering emits. Receives the app identity — unlike deploy's env-arg-free `providers()`, local providers are emulator clients and must know which app they provision for. */
  providers(input: LocalTargetProvidersInput): Layer.Layer<never>;
  /** A stable local identity — resolved without any platform call. */
  readonly container: ContainerDescriptor;
  /** Works out the platform variables' values, where deploy's preflight runs. Its payload reaches this extension's lowering as its preflight payload, as deploy's does. */
  preflight?(input: PreflightInput): Promise<DevPreflightResult>;
  /** Ensure the emulator daemons this topology's node kinds need are running, plus any per-node emulator state that must exist before converge (idempotent; daemons persist across sessions). */
  emulators?(input: LocalTargetEmulatorsInput): Promise<void>;
  /** The dev session's view of the running app. Core renders it and never learns an emulator's API. */
  attach(input: LocalTargetAttachInput): Promise<LocalTargetAttachment>;
  /** `--fresh`: remove every local trace of the dev instance — emulator instances, state, data. */
  teardown?(input: TeardownInput): Promise<void>;
  /**
   * The local copy of an app in one environment, read from the environment's
   * dev state directory alone — no entry, no graph, no container — so a
   * command can find or stop a running app without running the pipeline.
   * Undefined when this extension recorded nothing for the app there.
   */
  current?(input: LocalTargetCurrentInput): Promise<LocalTargetCurrentApp | undefined>;
}

/** What a local target's preflight found. */
export interface DevPreflightResult {
  readonly payload: PreflightPayload;
  /** The text of each plain platform variable a service reads, by name. Never a secret. */
  readonly plainVariableText: Readonly<Record<string, string>>;
}

export interface LocalTargetCurrentInput {
  /** Absolute path of the environment's dev state directory (`devEnvironmentDir`, under the cwd). */
  readonly devDir: string;
  readonly app: string;
  readonly environment: string;
}

/** The local copy of an app in one environment, as one extension recorded it. */
export interface LocalTargetCurrentApp {
  readonly app: string;
  /** Every node address recorded for the app. */
  readonly addresses: readonly string[];
  /** Where the node at `address` runs locally; undefined for an address not recorded. */
  locate(address: string): Promise<LocalNodeLocation | undefined>;
  /** Stops everything the target runs for the app (emulators and data persist); returns the nodes it stopped. */
  stop(): Promise<readonly LocalNodeStopped[]>;
}

/** A node's local whereabouts. `kind` is the target's word for the node (for Prisma Cloud: `service`, `database` or `bucket`). */
export type LocalNodeLocation =
  | {
      readonly address: string;
      readonly kind: string;
      readonly emulator: 'running';
      /** Absent when the emulator no longer has the node's instance. */
      readonly url?: string;
      /** The target's word for the node's state, shown to the user. */
      readonly state: string;
      readonly condition: LocalNodeCondition;
      /** Where the node's own output is written, when the target keeps it in a file. */
      readonly logPath?: string;
      /** The argv the node runs in place of an artifact, when it runs its build adapter's dev server (ADR-0056). */
      readonly command?: readonly string[];
    }
  | {
      readonly address: string;
      readonly kind: string;
      /** The emulator that runs the node is not running, so it has no URL or state to report. */
      readonly emulator: 'not-running';
    };

/**
 * What a node's state means for reaching it: `running` answers at its URL;
 * `stopped` was stopped and starts with the next `prisma dev`; `crashing`
 * exited and is being restarted or was held after repeated crashes;
 * `missing` is recorded but its emulator no longer has it.
 */
export type LocalNodeCondition = 'running' | 'stopped' | 'crashing' | 'missing';

export interface LocalNodeStopped {
  readonly address: string;
  readonly kind: string;
}

export interface LocalTargetProvidersInput {
  /** This extension's resolved local-target container (its `input.appName` is the emulator app namespace). */
  readonly container: ContainerInstance | undefined;
  /** Absolute path of the environment's dev state directory (`devEnvironmentDir`, under the cwd). */
  readonly devDir: string;
  /** The text of each plain platform variable a service reads, by name. Never a secret. */
  readonly plainVariableText: Readonly<Record<string, string>>;
  /** The app secrets the graph's platform secrets name, which `prisma dev` hands its converge worker thread in memory. A local deployment takes the text its secret `$platform` markers name from it. */
  readonly namedSecrets: NamedSecrets;
}

export interface LocalTargetEmulatorsInput {
  /** The loaded application graph — inspected for which node kinds need an emulator. */
  readonly graph: Graph;
  readonly container: ContainerInstance | undefined;
  /** Absolute path of the environment's dev state directory (`devEnvironmentDir`, under the cwd). */
  readonly devDir: string;
}

export interface LocalTargetAttachInput {
  readonly container: ContainerInstance | undefined;
  /** Absolute path of the environment's dev state directory (`devEnvironmentDir`, under the cwd). */
  readonly devDir: string;
}

export interface LocalTargetAttachment {
  /** Start every stopped service from its last deployment (the session-resume signal — a no-op converge cannot start anything). */
  startServices(): Promise<void>;
  /** Every service's local endpoint, for the front door. */
  endpoints(): Promise<readonly { readonly address: string; readonly url: string }[]>;
  /** Merged, line-oriented log stream across the app's services (including services that appear after later converges). `opts.tail` is how many trailing lines of existing history to emit before live output (default 0 — live only). `opts.addresses`, when given, follows only those services. Ends when `signal` aborts. */
  logs(
    signal: AbortSignal,
    opts?: { readonly tail?: number; readonly addresses?: readonly string[] },
  ): AsyncIterable<{ readonly service: string; readonly line: string }>;
  /**
   * Runs a command on the service's instance in place of its artifact, with the environment the
   * service's deployment would get. Returns once the command accepts connections on the instance's
   * port. `restarted` is whether a process was started; an unchanged command already running is
   * left alone (ADR-0056). Optional: a target without it cannot run a dev server.
   */
  serve?(input: {
    readonly address: string;
    readonly node: ServiceNode;
    readonly server: DevServer;
    /** The app configuration the command read for this environment. */
    readonly configuration: AppConfiguration;
    /** The app secrets the command read for this environment. */
    readonly secrets: AppSecrets;
  }): Promise<{ readonly restarted: boolean }>;
  /** Stop everything the target runs for the app, so nothing of it keeps running after the session (emulators and data persist). */
  stopApp(): Promise<void>;
  /**
   * Does what `stopApp()` does and returns only once it is done, without the event loop: for a
   * process that is exiting and cannot await. Optional: without it, an exit that interrupts
   * `stopApp()` leaves the app running.
   */
  stopAppBeforeExit?(): void;
}

/** `<cwd>/.prisma-composer/dev` — local dev's state directory (ADR-0041, ADR-0004's tool-state rule), holding one folder per environment. */
export const DEV_DIR = '.prisma-composer/dev';

/**
 * The folder, relative to the cwd, that holds one environment's local copy.
 * The environment name is percent-encoded (`encodeURIComponent`), so a name
 * with `/` stays one folder and `decodeURIComponent` gives the name back.
 */
export function devEnvironmentDir(environment: string): string {
  return `${DEV_DIR}/${encodeURIComponent(environment)}`;
}

/**
 * The file in an environment's folder that holds the environment's exact
 * name. On a case-insensitive filesystem `Dev` and `dev` share one folder;
 * the recorded name tells them apart.
 */
export const DEV_ENVIRONMENT_NAME_FILE = 'environment-name';

/**
 * True when an extension only participates in assembly (every `nodes` entry
 * is `kind: 'build'`, and it declares none of `providers`/`application`/
 * `provisions`/`container`) — it owns no resources or services, so it has
 * nothing to emulate and is exempt from local-target-capability requirements
 * (ADR-0041). Shared by `localTargetProviders` and every local-target hook
 * iteration.
 */
export function isBuildOnlyExtension(extension: ExtensionDescriptor): boolean {
  return (
    Object.values(extension.nodes).every((node) => node.kind === 'build') &&
    extension.providers === undefined &&
    extension.application === undefined &&
    extension.provisions === undefined &&
    extension.container === undefined
  );
}

/**
 * What one registry entry can do. The `kind` discriminant is checked at every
 * lookup site against what the site needs — a resource node looked up against
 * a `service` descriptor is an error naming (extension, type, expected kind).
 */
export type NodeDescriptor =
  | ({ readonly kind: 'resource' } & Lowering)
  | ({ readonly kind: 'service' } & ServiceLowering)
  | {
      readonly kind: 'build';
      assemble(input: AssembleInput): Promise<Bundle>;
      /**
       * How this app runs in development, or `undefined` when it has no dev server and is assembled instead.
       * Never spawns anything: it resolves paths and binaries and returns data (ADR-0056).
       */
      serve?(input: ServeInput): Promise<DevServer | undefined>;
    };

/** What a config adapter receives (ADR-0062). */
export interface ConfigAdapterInput {
  /** The environment's name, as `--environment` gave it. */
  readonly environment: string;
  /** The absolute directory of the prisma.config.ts that declares the `composer` section. A file adapter reads its files relative to it (ADR-0004). */
  readonly configDirectory: string;
}

/** The values one adapter returns, by name. */
export type ConfigValues = Readonly<Record<string, unknown>>;

/** A function in the `config` or `secrets` list of the `composer` section (ADR-0062): it receives the environment and returns that environment's values. Only a command's first Load calls it; a later Load, such as the one `lower()` runs, takes what the first one read. */
export type ConfigAdapter = (input: ConfigAdapterInput) => ConfigValues | Promise<ConfigValues>;

/** The app configuration (ADR-0062): what the `config` adapters return, merged by top-level key, a later adapter winning. It is the root's input, and under `prisma dev` it also holds the text of each plain platform variable. */
export type AppConfiguration = Readonly<Record<string, unknown>>;

/** The app secrets (ADR-0062): what the `secrets` adapters return, merged the same way. Every value is text. Nothing fills a platform variable from them. `prisma dev` hands the local target's providers the values under the secrets keys of the graph's secret sources, and Composer redacts those values wherever it prints. */
export type AppSecrets = Readonly<Record<string, string>>;

/** The app secrets under the secrets keys of the graph's secret sources, each with text. `prisma dev` hands them to the local target's providers, in memory. */
export type NamedSecrets = Readonly<Record<string, string>>;

/**
 * The config file's default export. `extensions` lists every extension the
 * app deploys through; `state` is the ONE state store per deploy — explicit,
 * platform-agnostic, never defaulted by an extension. `config` and `secrets`
 * list the adapters the app configuration and the app secrets come from.
 */
export interface PrismaAppConfig {
  /** The module whose default export is the app root, relative to `prisma.config.ts`. `--entry` overrides it. */
  readonly entry?: string;
  readonly extensions: ExtensionDescriptor[];
  readonly state: StateDescriptor;
  /** Where the app configuration comes from. Defaults to `[environmentVariables()]`; a list given here replaces the default. */
  readonly config?: readonly ConfigAdapter[];
  /** Where the app secrets come from. Defaults to `[environmentVariables()]`; a list given here replaces the default. */
  readonly secrets?: readonly ConfigAdapter[];
}

/** Typed identity — exists so the `composer` section of `prisma.config.ts` gets checked against PrismaAppConfig where it is written. */
export function defineConfig(config: PrismaAppConfig): PrismaAppConfig {
  return config;
}
